<?php
/** Printable box-office receipt. @package Theaterly */
if ( ! defined( 'ABSPATH' ) ) { exit; }
$currency = array( 'currency' => $order->get_currency() );
$bookings = WTBM_Booking_Service::bookings( $order->get_id() );
$rows = WTBM_Layout_Pro::get_booking_data_by_ids( $bookings );
$cashier = get_userdata( absint( $order->get_meta( '_wtbm_cashier_id' ) ) );
$created = $order->get_date_created();
$has_tender = '' !== $order->get_meta( '_wtbm_tender' ) && 'wtbm_cash' === $order->get_payment_method();
$tender = (float) $order->get_meta( '_wtbm_tender' );
$paid_total = $order->get_meta( '_wtbm_initial_paid_total' );
$change = max( 0, $tender - ( '' !== $paid_total ? (float) $paid_total : (float) $order->get_total() ) );
$logo_id = get_theme_mod( 'custom_logo' );
$logo = $logo_id ? wp_get_attachment_image_url( $logo_id, 'medium' ) : '';
?>
<!doctype html><html <?php language_attributes(); ?>><head><meta charset="<?php bloginfo( 'charset' ); ?>"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title><?php echo esc_html( sprintf( __( 'Receipt #%s', 'wptheaterly' ), $order->get_order_number() ) ); ?></title><link rel="stylesheet" href="<?php echo esc_url( WTBM_PLUGIN_URL . '/assets/admin/wtbm_receipt.css?ver=' . filemtime( WTBM_PLUGIN_DIR . '/assets/admin/wtbm_receipt.css' ) ); ?>"><style id="wtbm-print-page">@page{size:A4;margin:14mm}</style></head><body>
<div class="receipt-toolbar"><a href="<?php echo esc_url( admin_url( 'admin.php?page=mptrs_main_menu&tab_name=wtbm_bookings' ) ); ?>"><?php esc_html_e( '← Back to bookings', 'wptheaterly' ); ?></a><div><button type="button" data-print="a4"><?php esc_html_e( 'Print / Save PDF (A4)', 'wptheaterly' ); ?></button><button type="button" data-print="thermal"><?php esc_html_e( 'Print 80 mm receipt', 'wptheaterly' ); ?></button></div></div>
<main class="receipt-paper"><header class="receipt-header"><div><?php if ( $logo ) { ?><img class="receipt-logo" src="<?php echo esc_url( $logo ); ?>" alt="<?php echo esc_attr( get_bloginfo( 'name' ) ); ?>"><?php } ?><p class="receipt-brand"><?php echo esc_html( get_bloginfo( 'name' ) ); ?></p><p class="receipt-eyebrow"><?php esc_html_e( 'Box office', 'wptheaterly' ); ?></p></div><div class="receipt-heading"><h1><?php esc_html_e( 'Receipt', 'wptheaterly' ); ?></h1><strong>#<?php echo esc_html( $order->get_order_number() ); ?></strong><span class="receipt-status"><?php echo esc_html( $order->is_paid() ? __( 'Paid', 'wptheaterly' ) : wc_get_order_status_name( $order->get_status() ) ); ?></span></div></header>
<section class="receipt-info"><div><h2><?php esc_html_e( 'Customer', 'wptheaterly' ); ?></h2><?php foreach ( $rows as $row ) { ?><strong><?php echo esc_html( $row['name'] ); ?></strong><p><?php echo esc_html( $row['phone'] ); ?></p><?php } ?><?php if ( $order->get_billing_email() ) { ?><p><?php echo esc_html( $order->get_billing_email() ); ?></p><?php } ?></div><dl><dt><?php esc_html_e( 'Issued', 'wptheaterly' ); ?></dt><dd><?php echo esc_html( $created ? wp_date( get_option( 'date_format' ) . ' ' . get_option( 'time_format' ), $created->getTimestamp() ) : '—' ); ?></dd><dt><?php esc_html_e( 'Payment method', 'wptheaterly' ); ?></dt><dd><?php echo esc_html( $order->get_payment_method_title() ?: __( 'Not recorded', 'wptheaterly' ) ); ?></dd><?php if ( $cashier ) { ?><dt><?php esc_html_e( 'Served by', 'wptheaterly' ); ?></dt><dd><?php echo esc_html( $cashier->display_name ); ?></dd><?php } ?><?php if ( $order->get_meta( '_wtbm_payment_reference' ) ) { ?><dt><?php esc_html_e( 'Reference', 'wptheaterly' ); ?></dt><dd><?php echo esc_html( $order->get_meta( '_wtbm_payment_reference' ) ); ?></dd><?php } ?></dl></section>
<section class="receipt-items"><h2><?php esc_html_e( 'Tickets', 'wptheaterly' ); ?></h2><table><thead><tr><th><?php esc_html_e( 'Show and seats', 'wptheaterly' ); ?></th><th class="receipt-number"><?php esc_html_e( 'Qty', 'wptheaterly' ); ?></th><th class="receipt-number"><?php esc_html_e( 'Amount', 'wptheaterly' ); ?></th></tr></thead><tbody><?php foreach ( $rows as $row ) { $bid = $row['id']; $item = $order->get_item( absint( get_post_meta( $bid, 'wtbm_item_id', true ) ) ); ?><tr><td><strong><?php echo esc_html( $row['movie_name'] ); ?></strong><p><?php echo esc_html( $row['theater_name'] . ' · ' . $row['date'] . ' · ' . $row['time'] ); ?></p><p><?php esc_html_e( 'Seats:', 'wptheaterly' ); ?> <?php echo esc_html( $row['seat_number'] ?: __( 'No active seats', 'wptheaterly' ) ); ?></p></td><td class="receipt-number"><?php echo esc_html( get_post_meta( $bid, 'wtbm_number_of_seats', true ) ); ?></td><td class="receipt-number"><?php echo wp_kses_post( wc_price( $item ? $item->get_total() + $item->get_total_tax() : $row['amount'], $currency ) ); ?></td></tr><?php } ?></tbody></table></section>
<section class="receipt-totals"><dl><dt><?php esc_html_e( 'Subtotal', 'wptheaterly' ); ?></dt><dd><?php echo wp_kses_post( wc_price( $order->get_subtotal(), $currency ) ); ?></dd><?php if ( $order->get_discount_total() ) { ?><dt><?php esc_html_e( 'Discount', 'wptheaterly' ); ?></dt><dd>−<?php echo wp_kses_post( wc_price( $order->get_discount_total(), $currency ) ); ?></dd><?php } ?><?php foreach ( $order->get_fees() as $fee ) { ?><dt><?php echo esc_html( $fee->get_name() ); ?></dt><dd><?php echo wp_kses_post( wc_price( $fee->get_total(), $currency ) ); ?></dd><?php } ?><?php if ( $order->get_shipping_total() ) { ?><dt><?php esc_html_e( 'Shipping', 'wptheaterly' ); ?></dt><dd><?php echo wp_kses_post( wc_price( $order->get_shipping_total(), $currency ) ); ?></dd><?php } ?><dt><?php esc_html_e( 'Tax', 'wptheaterly' ); ?></dt><dd><?php echo wp_kses_post( wc_price( $order->get_total_tax(), $currency ) ); ?></dd><dt class="receipt-total"><?php esc_html_e( 'Total', 'wptheaterly' ); ?></dt><dd class="receipt-total"><?php echo wp_kses_post( wc_price( $order->get_total(), $currency ) ); ?></dd><?php if ( $order->get_total_refunded() ) { ?><dt><?php esc_html_e( 'Recorded refunds', 'wptheaterly' ); ?></dt><dd>−<?php echo wp_kses_post( wc_price( $order->get_total_refunded(), $currency ) ); ?></dd><dt><?php esc_html_e( 'Total after refunds', 'wptheaterly' ); ?></dt><dd><?php echo wp_kses_post( wc_price( max( 0, $order->get_total() - $order->get_total_refunded() ), $currency ) ); ?></dd><?php } ?><?php if ( $has_tender ) { ?><dt><?php esc_html_e( 'Cash received', 'wptheaterly' ); ?></dt><dd><?php echo wp_kses_post( wc_price( $tender, $currency ) ); ?></dd><dt><?php esc_html_e( 'Change returned', 'wptheaterly' ); ?></dt><dd><?php echo wp_kses_post( wc_price( $change, $currency ) ); ?></dd><?php } ?><?php if ( $order->needs_payment() ) { ?><dt><?php esc_html_e( 'Amount due', 'wptheaterly' ); ?></dt><dd><?php echo wp_kses_post( wc_price( $order->get_total(), $currency ) ); ?></dd><?php } ?></dl></section>
<?php foreach ( $order->get_items() as $item ) { $pricing = $item->get_meta( '_wtbm_pricing_details' ); if ( ! is_array( $pricing ) || empty( $pricing['rules'] ) ) { continue; } ?>
<section class="receipt-info"><div><h2><?php esc_html_e( 'Applied pricing rules', 'wptheaterly' ); ?></h2><p><?php echo esc_html( implode( ', ', array_column( $pricing['rules'], 'name' ) ) ); ?></p></div><dl><dt><?php esc_html_e( 'Base seat total', 'wptheaterly' ); ?></dt><dd><?php echo wp_kses_post( wc_price( $pricing['base'], $currency ) ); ?></dd><dt><?php echo esc_html( sprintf( $pricing['percent'] < 0 ? __( 'Price decrease (%s%%)', 'wptheaterly' ) : __( 'Price increase (%s%%)', 'wptheaterly' ), abs( $pricing['percent'] ) ) ); ?></dt><dd><?php echo esc_html( $pricing['percent'] < 0 ? '−' : '+' ); echo wp_kses_post( wc_price( abs( $pricing['price'] - $pricing['base'] ), $currency ) ); ?></dd></dl></section>
<?php } ?>
<footer class="receipt-footer"><strong><?php esc_html_e( 'Thank you. Enjoy the show!', 'wptheaterly' ); ?></strong><p><?php echo esc_html( get_bloginfo( 'name' ) ); ?> · <?php echo esc_html( wp_parse_url( home_url(), PHP_URL_HOST ) ); ?></p><p><?php esc_html_e( 'Keep this receipt for your records.', 'wptheaterly' ); ?></p></footer></main>
<p class="receipt-print-help"><?php esc_html_e( 'For A4, choose A4 paper or Save as PDF. For thermal printing, select your 80 mm printer and paper size. Disable browser headers and footers in the print dialog.', 'wptheaterly' ); ?></p>
<script src="<?php echo esc_url( WTBM_PLUGIN_URL . '/assets/admin/wtbm_receipt.js?ver=' . filemtime( WTBM_PLUGIN_DIR . '/assets/admin/wtbm_receipt.js' ) ); ?>"></script></body></html>
